<?php
$member = isset($_GET['member']) ? (string)$_GET['member'] : (isset($_POST['member_id']) ? (string)$_POST['member_id'] : '');
$positionId = isset($_GET['position']) ? (string)$_GET['position'] : (isset($_POST['position_id']) ? (string)$_POST['position_id'] : '');
if (!preg_match('/^TW-MEMBER-[A-Za-z0-9_-]+$/',$member) || !preg_match('/^[A-Za-z0-9_-]+$/',$positionId)) { http_response_code(400); exit('Invalid challenge target.'); }
$profileFile = __DIR__ . '/profiles-public/' . $member . '.json';
$profile = is_file($profileFile) ? json_decode((string)file_get_contents($profileFile), true) : null;
if (!is_array($profile)) { http_response_code(404); exit('Profile not found.'); }
$position = null; foreach (($profile['positions'] ?? []) as $p) { if (($p['position_id'] ?? '') === $positionId) { $position = $p; break; } }
if (!$position) { http_response_code(404); exit('Position not found.'); }
$notice='';$noticeClass='';
$types=['source/authenticity','provenance','chronology','translation/language','context','logic','counterevidence','assumption','omitted alternative'];
$targets=['p','not-p','evidence-for-p','evidence-for-not-p','assumption','logic','scope/definition'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $honeypot=trim((string)($_POST['website']??'')); $type=trim((string)($_POST['challenge_type']??'')); $target=trim((string)($_POST['target_side']??''));
  $argument=trim((string)($_POST['argument']??'')); $source=trim((string)($_POST['source']??'')); $materiality=trim((string)($_POST['materiality']??'')); $name=trim((string)($_POST['display_name']??'')); $email=trim((string)($_POST['email']??''));
  if ($honeypot!=='') { http_response_code(400); $notice='Submission rejected.'; $noticeClass='error'; }
  elseif (!in_array($type,$types,true) || !in_array($target,$targets,true) || strlen($argument)<20 || strlen($materiality)<10) { $notice='Please identify the exact proposition/evidence target and explain why your evidence materially changes it.'; $noticeClass='error'; }
  elseif ($email!=='' && !filter_var($email,FILTER_VALIDATE_EMAIL)) { $notice='Please enter a valid email address or leave it blank.'; $noticeClass='error'; }
  else {
    $record=['challenge_id'=>'TW-MCH-'.gmdate('YmdHis').'-'.bin2hex(random_bytes(3)),'member_id'=>$member,'position_id'=>$positionId,'submitted_at'=>date(DATE_ATOM),'challenge_type'=>$type,'target_side'=>$target,'argument'=>$argument,'source'=>$source,'materiality'=>$materiality,'display_name'=>$name,'email'=>$email,'battle_invite'=>isset($_POST['battle_invite'])?'requested':'none','status'=>'pending-review'];
    $base=dirname((string)($_SERVER['DOCUMENT_ROOT']??__DIR__),1).'/private/trust-worthy/member-challenges'; if(!is_dir($base)){@mkdir($base,0700,true);} $file=$base.'/'.preg_replace('/[^A-Za-z0-9_-]/','_',$record['challenge_id']).'.json';
    if(is_dir($base)&&is_writable($base)&&file_put_contents($file,json_encode($record,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX)!==false){@chmod($file,0600);$notice='Challenge received. Trust-Worthy must independently investigate the evidence. A live Theology Battle occurs only if the challenged member accepts.';$noticeClass='success';} else {http_response_code(503);$notice='The challenge could not be stored safely yet. Private intake storage must be configured before launch.';$noticeClass='error';}
  }
}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
