<main><section class="hero"><div class="container"><div class="case-id"><?= e($member) ?> · <?= e($positionId) ?></div><h1 style="font-size:clamp(2.7rem,6vw,5rem)">Challenge the proposition.</h1><p class="lead"><strong>P:</strong> <?= e($position['p']) ?></p><?php if(!empty($position['not_p'])):?><p class="lead"><strong>not-P:</strong> <?= e($position['not_p']) ?></p><?php endif;?><div class="notice">Challenge the claim, evidence, translation, context, assumptions, or logic. Do not attack the member.</div></div></section>
<section class="section"><div class="container"><?php if($notice):?><div class="notice <?= e($noticeClass) ?>"><?= e($notice) ?></div><?php endif;?><form method="post" class="panel"><input type="hidden" name="member_id" value="<?= e($member) ?>"><input type="hidden" name="position_id" value="<?= e($positionId) ?>"><div style="position:absolute;left:-10000px" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="form-grid"><div class="field"><label>Challenge type</label><select name="challenge_type" required><option value="">Choose one</option><?php foreach($types as $t):?><option><?= e($t) ?></option><?php endforeach;?></select></div><div class="field"><label>Target</label><select name="target_side" required><option value="">Choose one</option><?php foreach($targets as $t):?><option value="<?= e($t) ?>"><?= e($t) ?></option><?php endforeach;?></select></div><div class="field full"><label>Your argument</label><textarea name="argument" maxlength="6000" required></textarea></div><div class="field full"><label>Source URL or citation</label><input name="source" maxlength="1000"></div><div class="field full"><label>Why does this materially change the proposition?</label><textarea name="materiality" maxlength="3000" required></textarea></div><div class="field"><label>Public display name (optional)</label><input name="display_name" maxlength="100"></div><div class="field"><label>Email for follow-up (optional, private)</label><input name="email" type="email" maxlength="254"></div><div class="field full"><label><input type="checkbox" name="battle_invite" value="1"> Invite this member to an opt-in live Theology Battle if the challenge passes intake review.</label></div></div><button class="button" type="submit">Submit Evidence Challenge</button></form></div></section></main><footer><div class="container">No forced debates. Evidence challenges may stand asynchronously; live battles require acceptance.</div></footer></body></html>